import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        t = int(next(iterator))
    except StopIteration:
        return

    results = []

    for _ in range(t):
        s = next(iterator)
        c = next(iterator)

        found = False
        n = len(s)
        for i, char in enumerate(s):
            if char == c:
                left_count = i
                right_count = n - 1 - i
                if left_count % 2 == 0 and right_count % 2 == 0:
                    found = True
                    break

        if found:
            results.append("YES")
        else:
            results.append("NO")

    print("\n".join(results))

if __name__ == "__main__":
    solve()
